!function(a){function n(n){for(var r,i,o=n[0],p=n[1],c=n[2],d=0,g=[];d<o.length;d++)i=o[d],Object.prototype.hasOwnProperty.call(m,i)&&m[i]&&g.push(m[i][0]),m[i]=0;for(r in p)Object.prototype.hasOwnProperty.call(p,r)&&(a[r]=p[r]);for(l&&l(n);g.length;)g.shift()();return t.push.apply(t,c||[]),e()}function e(){for(var a,n=0;n<t.length;n++){for(var e,i=t[n],o=!0,p=1;p<i.length;p++)e=i[p],0!==m[e]&&(o=!1);o&&(t.splice(n--,1),a=r(r.s=i[0]))}return a}function r(n){if(i[n])return i[n].exports;var e=i[n]={i:n,l:!1,exports:{}};return a[n].call(e.exports,e,e.exports,r),e.l=!0,e.exports}var i={},m={43:0},t=[];r.m=a,r.c=i,r.d=function(a,n,e){r.o(a,n)||Object.defineProperty(a,n,{enumerable:!0,get:e})},r.r=function(a){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(a,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(a,"__esModule",{value:!0})},r.t=function(a,n){if(1&n&&(a=r(a)),8&n)return a;if(4&n&&"object"==typeof a&&a&&a.__esModule)return a;var e=Object.create(null);if(r.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:a}),2&n&&"string"!=typeof a)for(var i in a)r.d(e,i,function(n){return a[n]}.bind(null,i));return e},r.n=function(a){var n=a&&a.__esModule?function(){return a.default}:function(){return a};return r.d(n,"a",n),n},r.o=function(a,n){return Object.prototype.hasOwnProperty.call(a,n)},r.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var l=p;t.push([188,0]),e()}({188:function(a,n,e){"use strict";e.r(n);var r=e(0);Object(r.a)("de","army",e(189),e(1))},189:function(a){a.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"20mm Flak38型高射炮","description":"<p>20mm Flak38型高射炮是在20mm Flak30型高射炮基础上进行改进的，改进后实际射速从Flak30的120发/分钟提高至220发/分钟，并通过对转动机械的改造提升了炮管横向与纵向的移动速度，但由于Flak38与Flak30都使用了相同的弹药，所以总体性能差别并不大，但后来生产的20mm Flak38型四联高射炮则威力大大提高，四支炮管同时射出的炮弹实际射速高达800发/分钟（理论上为1800发/分钟），由此成为了德军火力凶猛的杀器。</p><p>20mm Flak38型单管高射炮在1939年开始装备德军，四联高射炮则在1940年开始生产并进入德军部队。在空军高射炮部队中，它主要担负防空任务，但也经常为陆军作地面火力支援；在陆军部队中，则更多地用作对装甲车、轻型坦克的攻击与对敌方集群冲锋士兵的大量杀伤。1941年夏季，德军入侵苏联，在乌克兰西部的一次战斗，德军空军地面部队用20mm高射炮击毁了10辆苏军轻型坦克，因此，20mm Flak38型高射炮成为了德军防空与地面作战的有力武器。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonFlak38_11.jpg","description":"<h6>20mm Flak30型高射炮</h6><p></p><p>技术数据：</p><p>单管火炮口径：20mm；</p><p>炮架长：4.30米，宽2.40米，高2.20米；</p><p>炮管长：2.25米；</p><p>火炮重：战斗0.420吨，运输0.750吨（四联炮：战斗1.514吨，运输2.212吨）；</p><p>火炮射界（水平方向）：360度，火炮射角（垂直方向）：-10～90度；</p><p>实际射速：220发/分钟；（四联炮：800发/分钟）；</p><p>最远射程：4800米，有效射高：2200米；</p><p>炮弹初速：900米/秒。</p>","caption":""}],"part2title":"战场上的20mm Flak38型高射炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonFlak38_21.jpg","description":"德军将20mm Flak38型四联高射炮放置在渡轮上，以保卫防空气球部队。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_22.jpg","description":"冬季行动，东线苏联战场俄罗斯地区，一门德国空军高炮部队的20毫米Flak38型四联高射炮在村庄外雪地上对空警戒，该炮盾已被涂成白色，炮组人员都穿着白色的冬季服装，以便更好地伪装。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_23.jpg","description":"20mm Flak38型四联高射炮有两个脚踏板，每个脚踏板控制两个对角线炮管的发射。在一对炮管发射同时，供给另一对炮管的弹匣可以在不要求停止射击的情况下进行更换。同时踩下两个脚踏板即可发射全部四门炮，图中就是战斗中四炮齐发的状态；在该炮的炮架下周围排列着装有备用炮弹的弹药箱。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_24.jpg","description":"德空军高炮部队安置在自行马车上的一门20mm Flak38型四联高射炮，炮组人员正在跟踪一个飞行目标。炮长正在等待测距仪操作员报读数据，以便在下达命令开火之前，制定出与目标相配的最佳射击范围。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_25.jpg","description":"1942年，东线苏联战场，德军第26号装甲列车上的一门20mm Flak38型四联高射炮。为了减小火车在行驶过程中的空气阻力，已将该炮的装甲护罩的侧面板向后折叠。在德军的装甲列车上，都会装备此炮以作防空和防地面袭击用。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_26.jpg","description":"在东线苏联战场上配合地面作战的一门20mm Flak38型高射炮，随着附近烟雾的蔓延，炮组人员正用望远镜观察炮位侧面的情况，以寻找更多射击目标。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_27.jpg","description":"一门德军20mm Flak38型四联高射炮正在测距操作员的R36型1米测距仪引导下搜寻空中目标，炮位中，一名炮手将操纵杆抬高到足以能将炮压低以打击地面目标的位置。机组人员还在炮盾上披挂了一块迷彩布为高射炮作伪装。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_28.jpg","description":"安装在德国本土防空炮台上的德国空军高射炮部队的一门20mm Flak38型四联高射炮。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_29.jpg","description":"在敌机来袭之际，身穿迷彩服的德国空军高炮兵已作好戒备，该门20毫米Flak38型防空炮安装在Sdkfz 7半履带车辆上，以便能随时机动。另外，该炮的炮盾属于早期制作的式样。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_30.jpg","description":"1944年，西线战场意大利，德国空军高射炮部队的一门20mm Flak38型高射炮正在向来袭的盟军飞机进行射击。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_31.jpg","description":"德军高炮部队的一门20mm Flak38型四联高射炮的炮组成员正在合力将高射炮转移到新阵地上。由于火炮不算太重，所以推动时并不会感到很困难。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_32.jpg","description":"1943年，正在克罗地亚杜布罗夫尼克港（Dubrovnik）作防空戒备的德军高炮部队一门20mm Flak38型四联高射炮。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_33.jpg","description":"1945年1月15日，德国战场，守卫莱茵河畔雷马根（Remagen）吕登道夫大桥（Ludendorff Bridge）的德空军高射炮部队一门20mm Flak38型高射炮。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_34.jpg","description":"1943年8月，东线苏联战场，一辆SdKfz 7/1半履带装甲车上的20mm Flak38型四联高射炮正与苏联飞机交战。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_35.jpg","description":"德空军高射炮部队一门20mm Flak38型四联高射炮安装在铁路站台上，用于铁道设施的保护。图中该炮右下角的士兵正在装弹，另外还有两名操炮士兵，一名负责左上和右下两支炮管的射击，另一名则负责右上和左下两支炮管的射击。枪管发射时，装弹机可以自动更换弹匣。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak38_36.jpg","description":"安装在已作好伪装的半履带装甲车SdKfz 10/4平台上的德军一门20mm Flak38型单管高射炮（德军部队也有装备单管的20mm Flak38型高射炮）。从炮组士兵制服上的白领标识可知，这是隶属于“赫尔曼·戈林”师（Hermann Goring Division）的部队，这些安装高射炮的装甲车主要是作地面机动火力支援用。","caption":""}]}')}});